42	  input: ValidateWidgetEmbedMutationInput
43	): ValidateWidgetEmbedMutationResult {
44	  // REQ-19/INV-04: a widget instance's own bodyJson must never carry a widgetEmbed node at rest,
45	  // regardless of nesting depth — the caller passes the flattened resultingEmbeds list, so depth
46	  // is already erased; only "host is a widget, and at least one embed would result" matters.
47	  if (input.hostEntryType === WIDGET_CONTENT_TYPE && input.resultingEmbeds.length > 0) {
48	    return { valid: false, reason: "recursion" };
