 99	export async function resolvePageWidgets(required: ResolvePageWidgetsRequired): Promise<ResolvePageWidgetsResult> {
100	  const { deps, input } = required;
101	  const context: WidgetResolveContext = { workspaceId: input.workspaceId, preview: false };
102	
103	  // 1. Region -> widget_area -> ordered, enabled placement list.
104	  const regionPlacements = new Map<WidgetRegionKey, WidgetPlacementNode[]>();
105	  for (const regionKey of input.resolvedRegions) {
106	    regionPlacements.set(regionKey, []);
107	    const binding = await deps.bindingRepo.findByRegion({ workspaceId: input.workspaceId, regionKey });
108	    if (!binding) continue;
109	    const areaEntry = await deps.entryRepo.findById({ workspaceId: input.workspaceId, id: binding.areaEntryId });
110	    if (!areaEntry || areaEntry.type !== WIDGET_AREA_CONTENT_TYPE) continue;
111	    const payload = parseWidgetAreaPayload(areaEntry.fieldsJson);
112	    regionPlacements.set(
113	      regionKey,
114	      payload.doc.placements.filter((placement) => placement.enabled)
115	    );
116	  }
117	
118	  // 2. Inline embeds from the page entry's bodyJson (REQ-21/23).
119	  let inlineEmbeds: InlineEmbedRef[] = [];
120	  if (input.pageEntryId) {
121	    const pageEntry = await deps.entryRepo.findById({ workspaceId: input.workspaceId, id: input.pageEntryId });
122	    if (pageEntry) collectWidgetEmbeds(pageEntry.bodyJson, inlineEmbeds);
123	  }
124	
125	  // 3. One batched widget-instance load for every distinct widget referenced on the page (REQ-24 —
126	  // see this file's header for why `listByWorkspace` stands in for a literal `WHERE id IN (...)`).
127	  const referencedIds = new Set<UUID>();
128	  for (const placements of regionPlacements.values()) {
129	    for (const placement of placements) referencedIds.add(placement.widgetEntryId);
130	  }
131	  for (const embed of inlineEmbeds) referencedIds.add(embed.widgetEntryId);
132	
133	  const widgetRows =
134	    referencedIds.size > 0 ? await deps.entryRepo.listByWorkspace({ workspaceId: input.workspaceId, type: WIDGET_CONTENT_TYPE }) : [];
135	
136	  // 4. Build WidgetInstanceView list (skipping missing/trashed/purged targets — REQ-27's failure
137	  // taxonomy handles them as "unresolved", not a crash), grouped by type.
138	  const byType = new Map<WidgetTypeKey, WidgetInstanceView[]>();
139	  for (const row of widgetRows) {
140	    if (!referencedIds.has(row.id)) continue;
141	    const payload = parseWidgetInstancePayload(row.fieldsJson);
142	    if (payload.status === "trash" || payload.status === "purged") continue;
143	    const list = byType.get(payload.widgetType) ?? [];
144	    list.push({ id: row.id, widgetType: payload.widgetType, config: payload.config as JsonObject });
145	    byType.set(payload.widgetType, list);
146	  }
147	
148	  // 5. At most one resolveWidgetType (=> at most one resolveMany) call per distinct type (REQ-24).
149	  const resolvedById = new Map<UUID, WidgetResolveResult>();
150	  for (const [typeKey, instances] of byType) {
151	    const results = await resolveWidgetType(typeKey, instances, context);
152	    for (const [id, result] of results) resolvedById.set(id, result);
153	  }
154	
155	  // 6. Assemble region -> IR[] (missing/failed placements degrade to the REQ-28 placeholder).
156	  const regions: Record<WidgetRegionKey, WidgetRenderIR[]> = {};
157	  for (const [regionKey, placements] of regionPlacements) {
158	    regions[regionKey] = placements.map((placement) => toRenderIr(resolvedById.get(placement.widgetEntryId)));
159	  }
160	
161	  // 7. Assemble placementId -> IR for inline embeds.
162	  const inlineResolved = new Map<UUID, WidgetRenderIR>();
163	  for (const embed of inlineEmbeds) {
164	    inlineResolved.set(embed.placementId, toRenderIr(resolvedById.get(embed.widgetEntryId)));
165	  }
166	
167	  return { regions, inlineResolved };
