102	function clampResolveResult(result: WidgetResolveResult, registration: WidgetTypeRegistration): WidgetResolveResult {
103	  if (!result.ok) return result;
104	  const maxItems = registration.clamps.maxItems;
105	  if (maxItems === undefined || !result.ir.children || result.ir.children.length <= maxItems) return result;
106	  return { ...result, ir: { ...result.ir, children: result.ir.children.slice(0, maxItems) } };
