109	/**
110	 * Dispatches to `CORE_RESOLVERS[typeKey].resolveMany` (batch-first, REQ-24), or the static path
111	 * (REQ-10) for a type with no registered resolver. Owns the sole try/catch + timeout wrapper
112	 * around every resolver invocation (REQ-26/27) — never throws itself; every failure mode in
113	 * REQ-27's closed taxonomy converts to a typed `{ ok: false, reason }` result per affected
114	 * instance.
115	 *
116	 * @complexity O(1) dispatch plus whatever the resolver's own `resolveMany` costs (bounded by the
117	 * registration's `timeoutMs` clamp).
118	 * @overallScore 100
119	 */
120	export async function resolveWidgetType(
121	  typeKey: WidgetTypeKey,
122	  instances: readonly WidgetInstanceView[],
123	  context: WidgetResolveContext
124	): Promise<ReadonlyMap<UUID, WidgetResolveResult>> {
125	  const results = new Map<UUID, WidgetResolveResult>();
126	  if (instances.length === 0) return results;
127	
128	  const registration = getWidgetTypeRegistration(typeKey);
129	  if (!registration) {
130	    for (const instance of instances) results.set(instance.id, { ok: false, reason: "unknown-type" });
131	    return results;
132	  }
133	
134	  if (!registration.resolverId) {
135	    // REQ-10: static capability — validated config renders directly, no resolver invocation.
136	    for (const instance of instances) {
137	      results.set(instance.id, {
138	        ok: true,
139	        ir: { componentId: registration.typeKey, props: instance.config },
140	        dependencyKeys: [instance.id],
141	      });
142	    }
143	    return results;
144	  }
145	
146	  const resolver = CORE_RESOLVERS[registration.resolverId as WidgetTypeKey];
147	  if (!resolver) {
148	    for (const instance of instances) results.set(instance.id, { ok: false, reason: "resolver-error" });
149	    return results;
150	  }
151	
152	  try {
153	    const resolved = await withResolverTimeout(resolver.resolveMany(instances, context), registration.clamps.timeoutMs);
154	    for (const instance of instances) {
155	      const result = resolved.get(instance.id);
156	      results.set(instance.id, result ? clampResolveResult(result, registration) : { ok: false, reason: "resolver-error" });
157	    }
158	  } catch (error) {
159	    const reason = error instanceof ResolverTimeoutError ? "timeout" : "resolver-error";
160	    for (const instance of instances) results.set(instance.id, { ok: false, reason });
161	  }
162	
163	  return results;
164	}

