107	  /** Manual `BEGIN IMMEDIATE`/`COMMIT`/`ROLLBACK` — mirrors `SqliteContentTypeRepo.transaction`. */
108	  async transaction<T>(fn: () => Promise<T>): Promise<T> {
109	    const client = (this.db as unknown as { $client: Database.Database }).$client;
110	    client.exec("BEGIN IMMEDIATE");
111	    try {
112	      const result = await fn();
113	      client.exec("COMMIT");
114	      return result;
115	    } catch (error) {
116	      client.exec("ROLLBACK");
117	      throw error;
118	    }
119	  }
