 8	import type { WidgetRegionBindingRow, WidgetRegionKey } from "./types";
 9	
10	/**
11	 * @file Real SQLite `WidgetRegionBindingRepoPort` adapter (ADR-006 rule-of-two "second adapter"
12	 * half — `repo.memory.ts`'s `InMemoryWidgetRegionBindingRepo` is the first), mirroring
13	 * `navigation/repo.sqlite.ts`'s `SqliteNavLocationBindingRepo` structurally: `upsert` uses
14	 * `onConflictDoUpdate` targeting the composite `UNIQUE(workspace_id, region_key)` index (a real
15	 * strengthening of INV-02 over the in-memory adapter's single-process-only guarantee).
16	 *
17	 * Architectural role:
18	 * Infrastructure adapter. No feature logic — `region-area-service.ts` owns every write decision;
19	 * this class only persists what it's told.
20	 */
21	
22	type BindingRow = typeof widgetRegionBindings.$inferSelect;
23	
24	function toRecord(row: BindingRow): WidgetRegionBindingRow {
25	  return {
26	    workspaceId: row.workspaceId,
27	    regionKey: row.regionKey,
28	    areaEntryId: row.areaEntryId,
29	    updatedAt: row.updatedAt,
30	  };
31	}
32	
33	export class SqliteWidgetRegionBindingRepo implements WidgetRegionBindingRepoPort {
34	  constructor(private readonly db: ContentDb) {}
35	
36	  async findByRegion(required: { workspaceId: UUID; regionKey: WidgetRegionKey }): Promise<WidgetRegionBindingRow | null> {
37	    return findOneBy(
38	      this.db,
39	      widgetRegionBindings,
40	      [eq(widgetRegionBindings.workspaceId, required.workspaceId), eq(widgetRegionBindings.regionKey, required.regionKey)],
41	      toRecord
42	    );
43	  }
44	
45	  async listByWorkspace(required: { workspaceId: UUID }): Promise<WidgetRegionBindingRow[]> {
46	    const rows = this.db
47	      .select()
48	      .from(widgetRegionBindings)
49	      .where(eq(widgetRegionBindings.workspaceId, required.workspaceId))
50	      .all();
51	    return rows.map(toRecord);
52	  }
53	
54	  async upsert(required: {
55	    workspaceId: UUID;
56	    regionKey: WidgetRegionKey;
57	    areaEntryId: UUID;
58	    updatedAt: string;
59	  }): Promise<WidgetRegionBindingRow> {
60	    const row = {
61	      workspaceId: required.workspaceId,
62	      regionKey: required.regionKey,
63	      areaEntryId: required.areaEntryId,
64	      updatedAt: required.updatedAt,
65	    };
66	    this.db
67	      .insert(widgetRegionBindings)
68	      .values(row)
69	      .onConflictDoUpdate({
70	        target: [widgetRegionBindings.workspaceId, widgetRegionBindings.regionKey],
71	        set: { areaEntryId: row.areaEntryId, updatedAt: row.updatedAt },
72	      })
73	      .run();
74	    return row;
75	  }
76	
77	  async markInactive(required: { workspaceId: UUID; regionKey: WidgetRegionKey }): Promise<void> {
78	    this.db
79	      .delete(widgetRegionBindings)
80	      .where(and(eq(widgetRegionBindings.workspaceId, required.workspaceId), eq(widgetRegionBindings.regionKey, required.regionKey)))
81	      .run();
82	  }
83	
84	  async rebuildForWorkspace(required: { workspaceId: UUID; bindings: readonly WidgetRegionBindingRow[] }): Promise<void> {
85	    this.db.delete(widgetRegionBindings).where(eq(widgetRegionBindings.workspaceId, required.workspaceId)).run();
86	    if (required.bindings.length === 0) return;
87	    this.db
88	      .insert(widgetRegionBindings)
89	      .values(
90	        required.bindings.map((binding) => ({
91	          workspaceId: binding.workspaceId,
92	          regionKey: binding.regionKey,
93	          areaEntryId: binding.areaEntryId,
94	          updatedAt: binding.updatedAt,
95	        }))
96	      )
97	      .run();
98	  }
99	}

