 2	import { getWidgetTypeRegistration } from "../registry";
 3	import type { WidgetResolveResult, WidgetResolver } from "../types";
 4	
 5	/**
 6	 * @file `recent-entries` widget resolver (SPEC-043 REQ-25, ADR-047 §9).
 7	 *
 8	 * Purpose:
 9	 * A bounded, clamped read over `entries`, reusing `features/entries/list.ts`'s existing
10	 * `EntryListPort.listByWorkspace` read-query shape (per the Coordinator's integration-points
11	 * guidance) rather than writing a second entries-listing code path. Not wired into `CORE_RESOLVERS`
12	 * at module load (needs an injected `EntryListPort` — see `create-core-resolvers.ts`'s
13	 * `wireCoreResolvers` for how a future boot pass populates it) and has no dedicated test in this
14	 * TDD slice — `resolver-service.integration.test.ts` exercises the `recent-entries` DISPATCH path
15	 * via a test-double resolver, not this real implementation; this file is nonetheless a real,
16	 * working resolver, not a placeholder.
17	 *
18	 * `categoryTermId` (REQ-32/EC-03) is a documented soft reference — this resolver does not filter by
19	 * it (no taxonomy dependency wired here), matching EC-03's explicit "may render as if the filter is
20	 * empty/unset" allowance.
21	 */
22	export interface RecentEntriesResolverDeps {
23	  entryList: EntryListPort;
24	}
25	
26	export function createRecentEntriesResolver(deps: RecentEntriesResolverDeps): WidgetResolver {
27	  return {
28	    async resolveMany(instances, context) {
29	      const registration = getWidgetTypeRegistration("recent-entries");
30	      const registryMax = registration?.clamps.maxItems ?? 20;
31	
32	      // One batched query for the whole call (REQ-24) — EntryListPort has no `findByIds` batch
33	      // primitive, so a single `listByWorkspace` scoped to the widget content type stands in for
34	      // the outline's literal "WHERE id IN (...)" shape without a second entries-listing path.
35	      const allEntries = await deps.entryList.listByWorkspace({ workspaceId: context.workspaceId });
36	      const published = allEntries
37	        .filter((entry) => entry.status === "published")
38	        .sort((a, b) => (a.updatedAt < b.updatedAt ? 1 : a.updatedAt > b.updatedAt ? -1 : 0));
39	
40	      const results = new Map<string, WidgetResolveResult>();
41	      for (const instance of instances) {
42	        const configuredMax = typeof instance.config.maxItems === "number" ? instance.config.maxItems : registryMax;
43	        // REQ-25: the registered clamp always wins, regardless of the instance's own config.
44	        const max = Math.max(0, Math.min(configuredMax, registryMax));
45	        const items = published.slice(0, max).map((entry) => ({ id: entry.id, title: entry.title, slug: entry.slug }));
46	
47	        results.set(instance.id, {
48	          ok: true,
49	          ir: {
50	            componentId: "recent-entries",
51	            props: {},
52	            children: items.map((item) => ({ componentId: "entry-summary", props: item })),
53	          },
54	          dependencyKeys: items.map((item) => item.id),
55	        });
56	      }
57	      return results;
58	    },
59	  };
60	}

