 5	/**
 6	 * @file `contact-form` widget resolver (SPEC-043 REQ-36..39, ADR-047 Debate Fold-In Amendment 4).
 7	 *
 8	 * Purpose:
 9	 * A thin, READ-ONLY adapter over `src/forms/`'s definition read side. Imports ONLY the read-only
10	 * `forms/ports.ts` module (`FormDefinitionRepoPort`) — never the Forms library's own submission
11	 * write path or its outbox-driven mail-notification module — so this file can never persist a
12	 * submission, send mail, rate-limit, or duplicate any part of the Forms pipeline (INV-08, hard
13	 * invariant; verified by a code-review-level grep over this whole package for those two module
14	 * names, which must return nothing).
15	 *
16	 * REQ-37 ("reads the referenced Forms definition's declared field vocabulary — never a hardcoded
17	 * field-type list") is honored here: `definition.fields` (Forms' own `FieldDescriptor[]`) is passed
18	 * through as IR props verbatim, not re-enumerated against a widget-local field-kind switch. The
19	 * actual submission still posts to Forms' existing public route unmodified (REQ-37's second half) —
20	 * that is a render-component/route concern, out of this resolver's scope (no HTTP route exists yet
21	 * for widgets in this slice; see the implementation report's scope-boundary notes).
22	 */
23	export interface ContactFormResolverDeps {
24	  formDefinitionRepo: FormDefinitionRepoPort;
25	}
26	
27	export function createContactFormResolver(deps: ContactFormResolverDeps): WidgetResolver {
28	  return {
29	    async resolveMany(instances, context) {
30	      const results = new Map<string, WidgetResolveResult>();
31	      for (const instance of instances) {
32	        const formDefinitionId =
33	          typeof instance.config.formDefinitionId === "string" ? instance.config.formDefinitionId : undefined;
34	        if (!formDefinitionId) {
35	          results.set(instance.id, { ok: false, reason: "invalid-config" });
36	          continue;
37	        }
38	
39	        const definition = await deps.formDefinitionRepo.findById({
40	          workspaceId: context.workspaceId,
41	          id: formDefinitionId,
42	        });
43	        // REQ-38/EC-05: a disabled OR missing/unreachable definition is the same failure-isolation
44	        // placeholder, never an error — Forms definitions are never deleted (SPEC-010 INV-08).
45	        if (!definition || definition.status !== "active") {
46	          results.set(instance.id, { ok: false, reason: "target-disabled" });
47	          continue;
48	        }
49	
50	        results.set(instance.id, {
51	          ok: true,
52	          ir: {
53	            componentId: "contact-form",
54	            props: {
55	              formDefinitionId: definition.id,
56	              // REQ-37: Forms' own declared field vocabulary, passed through verbatim — never a
57	              // hardcoded field-type list. Cast: FieldDescriptor[] has no index signature of its
58	              // own, but every field is plain JSON-serializable data (SPEC-010 forms/types.ts).
59	              fields: definition.fields as unknown as JsonObject,
60	              successMessage: typeof instance.config.successMessage === "string" ? instance.config.successMessage : null,
61	            },
62	          },
63	          dependencyKeys: [definition.id],
64	        });
65	      }
66	      return results;
67	    },
68	  };
69	}

