 10	/**
 11	 * @file Per-site content.db bootstrap (Drizzle over better-sqlite3).
 12	 *
 13	 * Purpose:
 14	 * Opens the SQLite file that backs one site's content, applies pragmas, runs the
 15	 * generated Drizzle migrations, and (if the caller supplies seed data) seeds
 16	 * first-run demo content.
 17	 *
 18	 * How it relates to the project:
 19	 * - The composition root (`server/deps.ts`) opens the db here, passing in its own
 20	 *   `server/seed.ts` demo data, and injects the typed Drizzle handle into the
 21	 *   per-feature `repo.sqlite.ts` adapters.
 22	 * - Schema is code-first (`infra/db/schema.ts`) → `infra/drizzle/` migrations, so
 23	 *   same schema maps cleanly to a future Postgres adapter (ADR-006 rule-of-two,
 24	 *   Payload's shared-schema shape).
 25	 * - ADR-042 item 3: this file previously imported `seededWorkspace`/`seededPosts`/
 26	 *   `seededPresentation` directly from `server/seed.ts` — infra depending on
 27	 *   server, a layer-direction violation with no discovered justification. Seed
 28	 *   data is now a parameter the composition root supplies (dependency inversion,
 29	 *   the same seam every port in this codebase already uses), not a value this
 30	 *   file reaches up to fetch itself.
 31	 *
 32	 * Architectural role:
 33	 * Infrastructure. Only adapters and the composition root touch Drizzle/SQLite;
 34	 * domain/slice code stays provider-agnostic.
 35	 */
 36	/**
 37	 * SPEC-016 (`core/gated-mutations`'s `db-ops.ts` adapter, ADR-041 §5): widened with `$client`
 38	 * (the raw `better-sqlite3` `Database` instance `drizzle()` already returns at runtime) so a
 39	 * restore-point capture can call the driver's online-backup API directly. Additive only — every
 40	 * existing caller that only used the Drizzle query surface is unaffected.
 41	 */
 42	export type ContentDb = BetterSQLite3Database<typeof schema> & { $client: Database.Database };
 43	
 44	/** Generated migrations live at `src/infra/drizzle/` (resolved from this file). */
 45	const MIGRATIONS_DIR = path.resolve(__dirname, "../drizzle");
 46	
 47	/** First-run demo content a caller may supply to `openContentDb`/`seedContentDb`. */
 48	export interface ContentDbSeedData {
 49	  workspace: typeof schema.workspaces.$inferInsert;
 50	  posts: Array<Omit<typeof schema.posts.$inferInsert, "bodyJson"> & { bodyJson: unknown }>;
 51	  presentation: typeof schema.presentationSettings.$inferInsert;
 52	}
 53	
 54	/**
 55	 * ADR-023 §2 — a caller-injected pre-open recovery hook, run against `filePath` BEFORE this
 56	 * function opens its own connection (dependency inversion, same pattern `seed` already uses —
 57	 * ADR-042 item 3's fix for exactly this "infra reaching up" shape: this file stays decoupled from
 58	 * `features/plugins/*`; the composition root wires the concrete
 59	 * `recoverIncompleteDataModuleMigrations` implementation). Optional and a no-op when omitted —
 60	 * correct for `:memory:` connections (nothing to recover) and every hermetic test call site.
 61	 */
 62	export type ContentDbRecoveryHook = (filePath: string) => void;
 63	
 64	/** Open (or create) the content.db, apply pragmas, migrate, and seed if empty and `seed` is given. */
 65	export function openContentDb(filePath: string, seed?: ContentDbSeedData, recover?: ContentDbRecoveryHook): ContentDb {
 66	  if (recover) recover(filePath);
 67	
 68	  const sqlite = new Database(filePath);
 69	  sqlite.pragma("journal_mode = WAL");
 70	  sqlite.pragma("foreign_keys = ON");
 71	  // SPEC-033 — defense in depth alongside `store-plugin.ts`'s identical fix: this connection can
 72	  // itself be the "second" connection relative to a separate one (e.g. the store plugin's own
 73	  // dedicated handle) transiently holding a lock. Retry internally rather than throwing immediately.
 74	  sqlite.pragma("busy_timeout = 5000");
 75	
 76	  const db = drizzle(sqlite, { schema }) as ContentDb;
 77	  migrate(db, { migrationsFolder: MIGRATIONS_DIR });
 78	  ensureWatermarkRow(db);
 79	  if (seed) seedContentDb(db, seed);
 80	  return db;
 81	}
 82	
 83	/**
 84	 * SPEC-016 (`core/gated-mutations/watermark.ts`) — guarantees the `database_write_watermark`
 85	 * singleton row (`id=1`) exists, independent of any demo-seed data. `INSERT OR IGNORE` keeps this
 86	 * idempotent across restarts on a persisted db, matching `seedContentDb`'s own "never re-seed an
 87	 * operator-edited db" guard, but for a bootstrap invariant rather than optional demo content.
 88	 */
 89	function ensureWatermarkRow(db: ContentDb): void {
 90	  db.run(sql`INSERT OR IGNORE INTO ${schema.databaseWriteWatermark} (id, value, last_stamped_at) VALUES (1, 0, NULL)`);
 91	}
 92	
 93	/**
 94	 * Seed the demo workspace/posts/presentation exactly once.
 95	 *
 96	 * Guarded by workspace slug so a persisted db (with the operator's own edits) is
 97	 * never re-seeded or overwritten on restart.
 98	 */
 99	export function seedContentDb(db: ContentDb, seed: ContentDbSeedData): void {
100	  const existing = db
101	    .select({ id: schema.workspaces.id })
102	    .from(schema.workspaces)
103	    .where(eq(schema.workspaces.slug, seed.workspace.slug))
104	    .all();
105	  if (existing.length > 0) return;
106	
107	  db.transaction((tx) => {
108	    tx.insert(schema.workspaces).values(seed.workspace).run();
109	    for (const post of seed.posts) {
110	      tx.insert(schema.posts)
111	        .values({ ...post, bodyJson: JSON.stringify(post.bodyJson) })
112	        .run();
113	    }
114	    tx.insert(schema.presentationSettings).values(seed.presentation).run();
115	  });
116	}

